// Fictional stops with OSRM road geometry; accelerated simulation, not live GPS.
const sampleRoutes=[
{id:'YGN-01',sme:'Golden Bloom · Sanchaung',customer:'May Thu · Bahan',start:[16.805,96.128],end:[16.818,96.153],via:[[16.805,96.137],[16.81,96.145]],parcel:'Linen shirt × 2'},
{id:'YGN-02',sme:'Lotus Living · Hlaing',customer:'Ei Mon · Kamayut',start:[16.847,96.126],end:[16.827,96.131],via:[[16.84,96.13],[16.833,96.129]],parcel:'Ceramic mug × 2'},
{id:'YGN-03',sme:'Urban Threads · Tamwe',customer:'Su Myat · Yankin',start:[16.817,96.175],end:[16.842,96.164],via:[[16.825,96.172],[16.834,96.168]],parcel:'Cotton tee × 3'},
{id:'YGN-04',sme:'Daily Goods · Dagon',customer:'Htet Aung · Botataung',start:[16.79,96.15],end:[16.772,96.174],via:[[16.783,96.157],[16.777,96.165]],parcel:'Daily essentials × 1'},
{id:'YGN-05',sme:'Bloom Studio · Mayangone',customer:'Wai Yan · Insein',start:[16.869,96.142],end:[16.89,96.105],via:[[16.878,96.133],[16.884,96.118]],parcel:'Gift box × 1'}];
sampleRoutes.forEach((r,i)=>{const road=roadRoutes[i];r.path=road.path;r.distance=road.distance;r.start=r.path[0];r.end=r.path[r.path.length-1];r.lengths=[0];for(let j=1;j<r.path.length;j++){const a=r.path[j-1],b=r.path[j];r.lengths.push(r.lengths[j-1]+Math.hypot((b[0]-a[0]),(b[1]-a[1])*Math.cos(a[0]*Math.PI/180)))}});
let riderMap=null,routeLayer=null,riderPin=null,startPin=null,endPin=null,simulationTimer=null,selectedRoute=0,simulationProgress=0;
const mapIcon=(label,color)=>L.divIcon({className:'',html:`<div style="background:${color};color:white;border:3px solid white;box-shadow:0 2px 8px #0004;border-radius:50%;width:34px;height:34px;display:grid;place-items:center;font-size:12px;font-weight:700">${label}</div>`,iconSize:[34,34],iconAnchor:[17,17]});
function stopSimulation(){if(simulationTimer!==null){clearInterval(simulationTimer);simulationTimer=null}$('#startSimulation').text(simulationProgress>=1?'Replay demo':'▶ Start simulation')}
function routePosition(route,progress){const path=route.path,lengths=route.lengths,target=Math.max(0,Math.min(1,progress))*lengths[lengths.length-1];let i=1;while(i<path.length-1&&lengths[i]<target)i++;const distance=lengths[i]-lengths[i-1],fraction=distance?(target-lengths[i-1])/distance:0;return path[i-1].map((v,j)=>v+(path[i][j]-v)*fraction)}
function updateSimulation(){let r=sampleRoutes[selectedRoute],pct=Math.round(simulationProgress*100);if(riderPin)riderPin.setLatLng(routePosition(r,simulationProgress));$('#routeProgress').text(pct+'%');$('#routeBar').css('width',pct+'%');$('#simStatus').text(pct>=100?'Demo delivered · Customer ထံရောက်ရှိပြီ':pct===0?'Ready at SME pickup · စတင်ရန် အသင့်':'In transit · Customer ဆီ သွားနေသည်');$('#routeStage').text(pct>=100?'✓ Delivered (demo)':pct===0?'SME pickup':'Rider en route');$('#pauseSimulation').prop('disabled',simulationTimer===null).css('opacity',simulationTimer===null?.45:1)}
function selectDemoRoute(index){stopSimulation();selectedRoute=index;simulationProgress=0;let r=sampleRoutes[index];$('#demoRoute').val(index);$('#routeInfo').text(r.sme+' → '+r.customer);$('#routeParcel').text(r.parcel+' · '+r.id+' · '+(r.distance/1000).toFixed(1)+' km road route');if(riderMap){[routeLayer,riderPin,startPin,endPin].forEach(layer=>{if(layer)riderMap.removeLayer(layer)});let path=r.path;routeLayer=L.polyline(path,{color:'#2563eb',weight:5,opacity:.85}).addTo(riderMap);startPin=L.marker(r.start,{icon:mapIcon('S','#334155')}).addTo(riderMap).bindPopup(esc(r.sme)+' · SME pickup');endPin=L.marker(r.end,{icon:mapIcon('C','#2563eb')}).addTo(riderMap).bindPopup(esc(r.customer)+' · Customer destination');riderPin=L.marker(r.start,{icon:mapIcon('R','#16805a'),zIndexOffset:500}).addTo(riderMap).bindPopup('Demo rider · simulated movement');riderMap.fitBounds(path,{padding:[45,45],maxZoom:14})}updateSimulation()}
const renderBeforeMap=render;
render=function(){stopSimulation();if(riderMap){riderMap.remove();riderMap=null}renderBeforeMap();if(role!=='rider'||page!=='My deliveries')return;
$('#content').prepend(`<section class="card overflow-hidden mb-6"><div class="p-5"><div class="flex flex-wrap gap-3 items-center justify-between"><div><h2 class="font-semibold">Yangon · SME → Customer simulation</h2><p class="text-xs muted mt-2">Sample routes ၅ ခု · Sample SME / Customer stops · OSRM road routes, accelerated rider demo.</p></div><button id="centerRider" class="field !w-auto text-xs">◎ Center on rider</button></div><label class="text-xs block mt-5">Select sample route<select id="demoRoute" class="field mt-2">${sampleRoutes.map((r,i)=>`<option value="${i}">${i+1}. ${r.sme} → ${r.customer}</option>`).join('')}</select></label><div class="bg-slate-50 rounded-xl p-4 mt-4"><b id="routeInfo" class="text-sm"></b><p id="routeParcel" class="text-xs muted mt-2"></p><div class="flex flex-wrap gap-3 mt-4"><button id="startSimulation" class="primary">▶ Start simulation</button><button id="pauseSimulation" class="field !w-auto text-xs">Ⅱ Pause</button><button id="resetSimulation" class="field !w-auto text-xs">↺ Reset</button><label class="text-xs self-center ml-auto">Speed <select id="simulationSpeed" class="border rounded p-2"><option value="1">1× · 10 sec</option><option value="2" selected>2× · 5 sec</option><option value="4">4× · 2.5 sec</option></select></label></div><div class="flex justify-between text-xs mt-4"><span id="simStatus"></span><span id="routeProgress">0%</span></div><div class="bg-slate-200 h-2 rounded-full mt-2 overflow-hidden"><div id="routeBar" class="bg-emerald-600 h-full" style="width:0%"></div></div></div></div><div id="riderMap" style="height:430px;z-index:0" aria-label="OpenStreetMap with simulated Yangon SME to customer route"></div><div class="p-4 flex flex-wrap gap-4 text-xs muted"><span>S · SME pickup</span><span>R · Demo rider</span><span>C · Customer</span><b id="routeStage" class="text-emerald-700 ml-auto"></b></div><p id="tileStatus" role="status" class="px-4 pb-4 text-xs muted">Simulation only · Road geometry: OSRM / OpenStreetMap · Accelerated simulation only, no live GPS or traffic ETA. Map tiles require internet.</p></section>`);
if(typeof L==='undefined'){$('#tileStatus').text('Map library unavailable. Refresh to retry.');return}
riderMap=L.map('riderMap',{scrollWheelZoom:false}).setView(sampleRoutes[selectedRoute].start,13);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).on('tileerror',()=>$('#tileStatus').text('Map tiles unavailable. Check internet. Road geometry stays available; no live GPS.')).addTo(riderMap);selectDemoRoute(selectedRoute)};
$(document).on('change','#demoRoute',function(){selectDemoRoute(+this.value)});
$(document).on('click','#startSimulation',function(){if(!riderMap)return;if(simulationTimer!==null)return;if(simulationProgress>=1)simulationProgress=0;simulationTimer=setInterval(()=>{simulationProgress=Math.min(1,simulationProgress+.01*Number($('#simulationSpeed').val()||1));updateSimulation();if(simulationProgress>=1){stopSimulation();updateSimulation();note('Demo route completed · '+sampleRoutes[selectedRoute].id)}},100);$('#startSimulation').text('Simulation running…');updateSimulation()});
$(document).on('click','#pauseSimulation',()=>{stopSimulation();updateSimulation()});$(document).on('click','#resetSimulation',()=>selectDemoRoute(selectedRoute));$(document).on('click','#centerRider',()=>{if(riderMap)riderMap.setView(routePosition(sampleRoutes[selectedRoute],simulationProgress),15)});window.addEventListener('pagehide',stopSimulation);render();
